/**
 * Cron-style trigger for the digest job.
 *
 * Owner D. The route is a trigger, not the job: `runDigestEmailJob` decides
 * which organizations are due based on their `digestHourUtc`, so calling this
 * every hour is correct and calling it twice in one hour is harmless.
 *
 * Must call (do not reimplement): runDigestEmailJob
 */

import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";

export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  try {
    assertCronSecret(request);

    const result = await runDigestEmailJob(new Date());
    return Response.json(result);
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Cron-style trigger for the usage rollup.
 *
 * Owner D. `OrganizationUsage` is a cached aggregate; the quota guards read it
 * rather than counting rows on every check, which is why it needs a periodic
 * recompute to stay honest.
 *
 * Must call (do not reimplement): runUsageRollupJob
 */

import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";

export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  try {
    assertCronSecret(request);

    const result = await runUsageRollupJob(new Date());
    return Response.json(result);
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Cron-style trigger for the overdue scan.
 *
 * Owner D. The job emits `issue.overdue`; the notification fan-out is a
 * subscriber, so this route never sends anything itself.
 *
 * Must call (do not reimplement): runOverdueIssueJob
 */

import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";

export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  try {
    assertCronSecret(request);

    const result = await runOverdueIssueJob(new Date());
    return Response.json(result);
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Shared JSON helpers for the route handlers.
 *
 * Owner D. Every handler under `src/app/api` returns the same envelope as the
 * Server Actions — `{ error: AppErrorShape }` on failure — so a client can use
 * one parser for both. The status code comes from `HTTP_STATUS_BY_CODE`, which
 * is the single mapping from domain error code to HTTP.
 */

import { HTTP_STATUS_BY_CODE, toAppError } from "@/lib/errors";
import type { AppErrorShape, ApiErrorBody } from "@/types/api";

/** Turns any thrown value into the JSON error envelope with the right status. */
export function errorResponse(error: unknown): Response {
  const shape: AppErrorShape = toAppError(error);
  const body: ApiErrorBody = { error: shape };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[shape.code] });
}

/** Builds the envelope for a failure the handler detected itself. */
export function failure(
  code: AppErrorShape["code"],
  message: string,
): Response {
  const body: ApiErrorBody = { error: { code, message } };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[code] });
}

/**
 * Cron endpoints are protected by a shared secret rather than a session — they
 * are called by the platform scheduler, which has no cookie jar.
 */
export function assertCronSecret(request: Request): void {
  const expected = process.env.TASKFLOW_CRON_SECRET;
  if (expected === undefined || expected.length === 0) {
    // No secret configured means cron is disabled rather than wide open.
    throw new CronAuthError("Cron trigger is not configured.");
  }
  if (request.headers.get("x-taskflow-cron") !== expected) {
    throw new CronAuthError("Bad cron secret.");
  }
}

export class CronAuthError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message: string) {
    super(message);
    this.name = "CronAuthError";
  }
}
import type {
  IsoTimestamp,
  OrgId,
  SubscriptionId,
  TenantScoped,
  Timestamps,
} from "./common";

export type PlanId = "free" | "starter" | "growth" | "enterprise";

export const PLAN_IDS: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export type BillingInterval = "monthly" | "annual";

export type SubscriptionStatus =
  | "trialing"
  | "active"
  | "past_due"
  | "canceled";

export interface Subscription extends Timestamps, TenantScoped {
  readonly id: SubscriptionId;
  readonly plan: PlanId;
  readonly interval: BillingInterval;
  readonly status: SubscriptionStatus;
  readonly seats: number;
  readonly currentPeriodStart: IsoTimestamp;
  readonly currentPeriodEnd: IsoTimestamp;
  readonly cancelAt: IsoTimestamp | null;
}

/** The resource dimensions every plan caps. Adding a field here ripples into
 *  `PLAN_LIMITS`, `BillingService`, the usage UI and the limit guards. */
export type LimitedResource =
  | "seats"
  | "projects"
  | "issuesPerProject"
  | "storageMb"
  | "apiRequestsPerHour"
  | "webhooks";

/** Result of a single quota check, returned by `BillingService.checkLimit`. */
export interface LimitCheck {
  readonly resource: LimitedResource;
  readonly plan: PlanId;
  readonly limit: number;
  readonly used: number;
  readonly remaining: number;
  readonly exceeded: boolean;
}

export interface Invoice extends Timestamps, TenantScoped {
  readonly id: string;
  readonly number: string;
  readonly amountCents: number;
  readonly currency: string;
  readonly periodStart: IsoTimestamp;
  readonly periodEnd: IsoTimestamp;
  readonly paidAt: IsoTimestamp | null;
}

export interface BillingSummary {
  readonly orgId: OrgId;
  readonly subscription: Subscription;
  readonly checks: readonly LimitCheck[];
  readonly upcomingInvoiceCents: number;
}
