/**
 * Billing-period arithmetic: where a period ends, what it costs and how much
 * of it is left. Pure functions only; every date is read and written in UTC.
 */
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const DAY_MS = 24 * 60 * 60 * 1000;

/** Months a period of the given interval spans, which is what prices multiply by. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Same day-of-month and time of day `months` later, or that month's last day
 * when it has no such day (31 Jan + 1 month → 28/29 Feb).
 */
export function addMonthsClamped(date: Date, months: number): Date {
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth() + months;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  const result = new Date(date.getTime());
  // Day 1 first, so moving the month can never overflow into the one after.
  result.setUTCFullYear(year, month, 1);
  result.setUTCDate(Math.min(date.getUTCDate(), lastDay));
  return result;
}

/** The end of a period that starts at `start`. */
export function periodEndFor(start: Date, interval: BillingInterval): Date {
  return addMonthsClamped(start, monthsInInterval(interval));
}

/** The full charge of one period: monthly price per seat × seats × months. */
export function periodChargeCents(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsInInterval(interval);
}

/**
 * Scales `fullCents` by the days left in the period over the days in it,
 * rounded down to whole cents.
 *
 * Days left are whole or started days from `now` to the period end — none once
 * the end has been reached. Days in the period are the whole days between its
 * start and end, at least one.
 */
export function prorateCents(
  fullCents: number,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  now: Date,
): number {
  const start = new Date(periodStart).getTime();
  const end = new Date(periodEnd).getTime();

  const daysInPeriod = Math.max(1, Math.round((end - start) / DAY_MS));
  const daysLeft = Math.max(0, Math.ceil((end - now.getTime()) / DAY_MS));

  return Math.floor((fullCents * daysLeft) / daysInPeriod);
}

/** Canonical stored form of an instant. */
export function stamp(date: Date): IsoTimestamp {
  return toIsoTimestamp(date);
}

