import type { Invoice } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

/** What a caller supplies for a new invoice; the number and payment state are ours. */
export type NewInvoiceLine = {
  readonly amountCents: number;
  readonly periodStart: IsoTimestamp;
  readonly periodEnd: IsoTimestamp;
};''')
sub(p, '''    .orderBy(desc(invoices.periodStart))
    .all();''', '''    .orderBy(desc(invoices.periodStart), desc(sql`${invoices}.rowid`))
    .all();''')
sub(p, '''export async function findInvoice(''', '''/**
 * Issues an unpaid USD invoice with the workspace's next free number. Runs on
 * the caller's transaction (it is synchronous on purpose) so the number
 * allocation and the insert commit together with whatever else the caller is
 * changing — nothing is invoiced twice, and nothing is changed without its invoice.
 */
export function issueInvoiceInTransaction(
  tx: DbTransaction,
  orgId: OrgId,
  line: NewInvoiceLine,
): Invoice {
  const stamp = toIsoTimestamp(new Date());
  const row = tx
    .insert(invoices)
    .values({
      id: newId(),
      orgId,
      number: nextInvoiceNumber(tx, orgId),
      amountCents: line.amountCents,
      currency: "usd",
      periodStart: line.periodStart,
      periodEnd: line.periodEnd,
      paidAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvoice(row);
}

/** `INV-00001`, `INV-00002`, … per workspace, skipping any number already taken. */
function nextInvoiceNumber(tx: DbTransaction, orgId: OrgId): string {
  const existing = tx
    .select({ value: count() })
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .get();

  let sequence = (existing?.value ?? 0) + 1;

  for (;;) {
    const candidate = `INV-${String(sequence).padStart(5, "0")}`;
    const taken = tx
      .select({ id: invoices.id })
      .from(invoices)
      .where(and(orgPredicate(invoices.orgId, orgId), eq(invoices.number, candidate)))
      .get();
    if (!taken) return candidate;
    sequence += 1;
  }
}

export async function findInvoice(''')

# subscription repository
p='src/server/repositories/subscription-repository.ts'
sub(p, 'import { and, eq, isNotNull, lte, ne } from "drizzle-orm";', 'import { and, eq, inArray, isNotNull, isNull, lte, ne } from "drizzle-orm";')
sub(p, 'import { getDb, subscriptions } from "@/server/db";', 'import { getDb, organizations, subscriptions } from "@/server/db";')
sub(p, 'import { toSubscription } from "./_mappers";\nimport type { BillingInterval, PlanId, Subscription } from "@/types/billing";',
'''import { issueInvoiceInTransaction } from "./invoice-repository";
import { toSubscription } from "./_mappers";
import type { NewInvoiceLine } from "./invoice-repository";
import type {
  BillingInterval,
  Invoice,
  PlanId,
  Subscription,
} from "@/types/billing";''')
open(p,'a').write('''
/** The columns a billing transition may rewrite. */
export type SubscriptionPatch = Partial<
  Pick<
    Subscription,
    | "plan"
    | "interval"
    | "status"
    | "seats"
    | "currentPeriodStart"
    | "currentPeriodEnd"
    | "cancelAt"
  >
>;

/** A subscription rewrite together with the invoices it brings. */
export type SubscriptionChange = {
  readonly patch: SubscriptionPatch;
  readonly invoices: readonly NewInvoiceLine[];
};

export type SubscriptionTransition = {
  readonly before: Subscription;
  readonly after: Subscription;
  readonly invoices: readonly Invoice[];
};

/**
 * Reads the org's subscription, lets `decide` turn it into a change and
 * commits that change and its invoices in one transaction. `decide` runs on
 * the row as it is inside the transaction and must be synchronous, which is
 * what makes a repeated or concurrent run see the earlier run's result and
 * decline (`null`) instead of charging again.
 */
export async function transactSubscription(
  orgId: OrgId,
  decide: (current: Subscription) => SubscriptionChange | null,
): Promise<SubscriptionTransition | null> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(subscriptions)
      .where(orgPredicate(subscriptions.orgId, orgId))
      .get();
    if (!current) throw new Error(`Subscription for org ${orgId} not found`);

    const before = toSubscription(current);
    const change = decide(before);
    if (change === null) return null;

    const row = tx
      .update(subscriptions)
      .set({ ...change.patch, updatedAt: toIsoTimestamp(new Date()) })
      .where(orgPredicate(subscriptions.orgId, orgId))
      .returning()
      .get();
    if (!row) throw new Error(`Subscription for org ${orgId} not found`);

    return {
      before,
      after: toSubscription(row),
      invoices: change.invoices.map((line) =>
        issueInvoiceInTransaction(tx, orgId, line),
      ),
    };
  });
}

/**
 * Feeds the billing-renewal job: every subscription that is billed or about to
 * end, except those of archived workspaces. Cross-tenant and unbatched by
 * design, it sweeps every org. Which of them are due is for the job to decide.
 */
export async function listRenewalCandidates(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .leftJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        inArray(subscriptions.status, ["active", "canceled"]),
        isNull(organizations.archivedAt),
      ),
    )
    .orderBy(subscriptions.createdAt, subscriptions.id)
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}
''')
EOF

