/**
 * Moves subscriptions on period by period: renews and invoices the active ones
 * whose period ended, and ends cancellations on their date.
 *
 * Must call (do not reimplement): emit, getPlanLimits, periodChargeCents, periodEndFor, parseIso
 */
import { getPlanLimits } from "@/config/plan-limits";
import { periodChargeCents, periodEndFor } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { announceInvoices } from "@/server/services/_invoicing";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { NewInvoiceLine } from "@/server/repositories/invoice-repository";
import type { SubscriptionChange } from "@/server/repositories/subscription-repository";
import type { BillingInterval, Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Where a cancelled subscription lands, on a fresh monthly period. */
const FALLBACK_PLAN = "free" as const;
const FALLBACK_INTERVAL: BillingInterval = "monthly";

/** A subscription this far behind is corrupt data, not a backlog to invoice. */
const MAX_PERIODS_PER_RUN = 1_200;

const logger = createLogger("billing-renewal-job");

type Period = { start: Date; end: Date };

/**
 * One pass over every live workspace's subscription.
 *
 * An active subscription whose period has ended is renewed once per elapsed
 * interval, each paid period invoiced at the current seat count. A cancelled
 * one is ended on its cancellation date — never before it — and drops to the
 * free plan. Trials and past-due subscriptions are not this job's business.
 *
 * Replay-safe: the decision is taken on the row inside the same transaction
 * that writes the result, so a second run at the same instant finds nothing
 * due, and an invoice is announced only by the run that wrote it.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const stamp = toIsoTimestamp(now);
    const candidates = await subscriptionRepo.listRenewalCandidates();

    for (const candidate of candidates) {
      if (!isDue(candidate, now)) continue;

      const orgId = candidate.orgId as OrgId;

      try {
        const transition = await subscriptionRepo.transactSubscription(
          orgId,
          (current) => renewalFor(current, now),
        );
        if (transition === null) continue;

        await announceInvoices(orgId, null, stamp, transition.invoices);

        if (
          transition.before.status === "canceled" &&
          transition.before.plan !== FALLBACK_PLAN
        ) {
          await emit("billing.plan_changed", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            from: transition.before.plan,
            to: FALLBACK_PLAN,
          });
        }

        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Whether `renewalFor` would have something to do for this row. */
function isDue(subscription: Subscription, now: Date): boolean {
  if (subscription.status === "active") {
    return parseIso(subscription.currentPeriodEnd).getTime() <= now.getTime();
  }
  if (subscription.status === "canceled") {
    return (
      subscription.cancelAt !== null &&
      parseIso(subscription.cancelAt).getTime() <= now.getTime()
    );
  }
  return false;
}

function renewalFor(
  current: Subscription,
  now: Date,
): SubscriptionChange | null {
  if (!isDue(current, now)) return null;
  return current.status === "canceled"
    ? cancellationFor(current, now)
    : renewalPeriodsFor(current, now);
}

/** The consecutive periods from the old period's end up to the first one that outlasts `now`. */
function renewalPeriodsFor(
  current: Subscription,
  now: Date,
): SubscriptionChange {
  const periods = periodsFrom(
    parseIso(current.currentPeriodEnd),
    current.interval,
    now,
  );
  const last = periods[periods.length - 1];
  if (last === undefined) throw new Error("No billing period was produced");

  const chargeCents = periodChargeCents(
    getPlanLimits(current.plan).priceCentsPerSeatMonthly,
    current.seats,
    current.interval,
  );
  const invoices: readonly NewInvoiceLine[] =
    current.plan === "free"
      ? []
      : periods.map((period) => ({
          amountCents: chargeCents,
          periodStart: toIsoTimestamp(period.start),
          periodEnd: toIsoTimestamp(period.end),
