    patch: {
      currentPeriodStart: toIsoTimestamp(last.start),
      currentPeriodEnd: toIsoTimestamp(last.end),
    },
    invoices,
  };
}

/**
 * The workspace is on the free plan from the cancellation date on, with a
 * monthly period that starts there. Free periods that have run out since are
 * rolled on in the same pass; without that the next run would still find work.
 */
function cancellationFor(
  current: Subscription,
  now: Date,
): SubscriptionChange {
  if (current.cancelAt === null) {
    throw new Error("Cancelled subscription has no cancellation date");
  }

  const periods = periodsFrom(
    parseIso(current.cancelAt),
    FALLBACK_INTERVAL,
    now,
  );
  const last = periods[periods.length - 1];
  if (last === undefined) throw new Error("No billing period was produced");

  return {
    patch: {
      plan: FALLBACK_PLAN,
      interval: FALLBACK_INTERVAL,
      status: "active",
      cancelAt: null,
      currentPeriodStart: toIsoTimestamp(last.start),
      currentPeriodEnd: toIsoTimestamp(last.end),
    },
    invoices: [],
  };
}

/**
 * Back-to-back periods starting at `from`, each starting where the one before
 * ended, stopping at the first whose end lies after `now`. Always at least one.
 */
function periodsFrom(
  from: Date,
  interval: BillingInterval,
  now: Date,
): readonly Period[] {
  const periods: Period[] = [];
  let start = from;

  do {
    if (periods.length >= MAX_PERIODS_PER_RUN) {
      throw new Error(`More than ${MAX_PERIODS_PER_RUN} periods are overdue`);
    }
    const end = periodEndFor(start, interval);
    periods.push({ start, end });
    start = end;
  } while (start.getTime() <= now.getTime());

  return periods;
}
