export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const stamp = toIsoTimestamp(now);
    const candidates = await subscriptionRepo.listRenewalCandidates();

    for (const candidate of candidates) {
      if (!isDue(candidate, now)) continue;

      const orgId = candidate.orgId as OrgId;

