import { describe, expect, it } from "vitest";
import {
  addMonthsClamped,
  monthsInInterval,
  periodChargeCents,
  periodEndFor,
  prorateCents,
} from "@/lib/billing-period";
import type { IsoTimestamp } from "@/types/common";

const iso = (value: string) => value as IsoTimestamp;
const at = (value: string) => new Date(value);

describe("lib/billing-period", () => {
  describe("periodEndFor", () => {
    it("ends a monthly period on the same day of the next month, at the same time", () => {
      expect(periodEndFor(at("2026-03-15T08:30:15.250Z"), "monthly").toISOString()).toBe(
        "2026-04-15T08:30:15.250Z",
      );
    });

    it("clamps to the last day of a shorter month", () => {
      expect(periodEndFor(at("2026-01-31T10:00:00.000Z"), "monthly").toISOString()).toBe(
        "2026-02-28T10:00:00.000Z",
      );
      expect(periodEndFor(at("2028-01-31T10:00:00.000Z"), "monthly").toISOString()).toBe(
        "2028-02-29T10:00:00.000Z",
      );
      expect(periodEndFor(at("2026-03-31T00:00:00.000Z"), "monthly").toISOString()).toBe(
        "2026-04-30T00:00:00.000Z",
      );
    });

    it("carries a clamped day forward when the next period starts where the last ended", () => {
      const first = periodEndFor(at("2026-01-31T00:00:00.000Z"), "monthly");
      const second = periodEndFor(first, "monthly");
      expect(first.toISOString()).toBe("2026-02-28T00:00:00.000Z");
      expect(second.toISOString()).toBe("2026-03-28T00:00:00.000Z");
    });

    it("rolls over the year end", () => {
      expect(periodEndFor(at("2026-12-31T23:59:59.999Z"), "monthly").toISOString()).toBe(
        "2027-01-31T23:59:59.999Z",
      );
    });

    it("ends an annual period on the same day and month of the next year", () => {
      expect(periodEndFor(at("2026-06-10T12:00:00.000Z"), "annual").toISOString()).toBe(
        "2027-06-10T12:00:00.000Z",
      );
      expect(periodEndFor(at("2028-02-29T12:00:00.000Z"), "annual").toISOString()).toBe(
        "2029-02-28T12:00:00.000Z",
      );
    });
  });

  describe("addMonthsClamped", () => {
    it("does not mutate its argument", () => {
      const start = at("2026-01-31T00:00:00.000Z");
      addMonthsClamped(start, 1);
      expect(start.toISOString()).toBe("2026-01-31T00:00:00.000Z");
    });
  });

  describe("periodChargeCents", () => {
    it("multiplies price, seats and months", () => {
      expect(monthsInInterval("monthly")).toBe(1);
      expect(monthsInInterval("annual")).toBe(12);
      expect(periodChargeCents(900, 4, "monthly")).toBe(3_600);
      expect(periodChargeCents(900, 4, "annual")).toBe(43_200);
    });
  });

  describe("prorateCents", () => {
    const start = iso("2026-06-01T00:00:00.000Z");
    const end = iso("2026-07-01T00:00:00.000Z"); // 30 days

    it("charges the whole amount at the start of the period", () => {
      expect(prorateCents(3_000, start, end, at("2026-06-01T00:00:00.000Z"))).toBe(3_000);
    });

    it("counts started days as whole days", () => {
      // 14 days and 22 hours left count as 15.
      expect(prorateCents(3_000, start, end, at("2026-06-16T02:00:00.000Z"))).toBe(1_500);
      // 15 days exactly left count as 15.
      expect(prorateCents(3_000, start, end, at("2026-06-16T00:00:00.000Z"))).toBe(1_500);
      // 1 hour left counts as 1.
      expect(prorateCents(3_000, start, end, at("2026-06-30T23:00:00.000Z"))).toBe(100);
    });

    it("rounds down to whole cents", () => {
      // 1900 × 7 / 30 = 443.33…
      expect(prorateCents(1_900, start, end, at("2026-06-24T00:00:00.000Z"))).toBe(443);
      // 100 × 29 / 30 = 96.66…
      expect(prorateCents(100, start, end, at("2026-06-02T00:00:00.000Z"))).toBe(96);
    });

    it("charges nothing once the period end has been reached", () => {
      expect(prorateCents(3_000, start, end, at("2026-07-01T00:00:00.000Z"))).toBe(0);
      expect(prorateCents(3_000, start, end, at("2026-07-09T00:00:00.000Z"))).toBe(0);
    });

    it("takes the days in the period as whole rounded days, at least one", () => {
      // 28 days.
      expect(
        prorateCents(
          2_800,
          iso("2026-02-01T00:00:00.000Z"),
          iso("2026-03-01T00:00:00.000Z"),
          at("2026-02-15T00:00:00.000Z"),
        ),
      ).toBe(1_400);
      // A period shorter than a day still counts as one day.
      expect(
        prorateCents(
          500,
          iso("2026-02-01T00:00:00.000Z"),
          iso("2026-02-01T06:00:00.000Z"),
          at("2026-02-01T03:00:00.000Z"),
        ),
      ).toBe(500);
    });
  });
});

