/**
 * Renewal, invoicing and cancellation as the hourly job performs them.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import { drain, enqueue, resetQueue } from "@/server/jobs";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SubscriptionRow } from "@/server/db";
import type { PlanId } from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { TaskflowEventType, TaskflowEventPayload, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let slugCounter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
});

afterEach(() => {
  resetQueue();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

function capture<K extends TaskflowEventType>(type: K): TaskflowEventPayload<K>[] {
  const seen: TaskflowEventPayload<K>[] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function tenantWith(
  plan: PlanId,
  state: Partial<
    Pick<
      SubscriptionRow,
      "interval" | "status" | "seats" | "currentPeriodStart" | "currentPeriodEnd" | "cancelAt"
    >
  >,
): Promise<Tenant> {
  slugCounter += 1;
  const tenant = await createTenant(`renewal-${slugCounter}`, plan);
  getDb()
    .update(subscriptions)
    .set({ plan, status: "active", ...state })
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
  return tenant;
}

async function subscriptionOf(tenant: Tenant) {
  const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
  if (!subscription) throw new Error("missing subscription");
  return subscription;
}

async function activityFor(tenant: Tenant, action: "billing.invoice_issued" | "billing.plan_changed") {
  const page = await activityRepo.listActivity({
    orgId: tenant.org.id,
    action: [action],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

async function notificationsFor(tenant: Tenant, recipient: keyof Tenant["userIds"]) {
  const page = await notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds[recipient],
    unreadOnly: false,
    kind: ["invoice_issued"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

const NOW = new Date("2026-06-15T12:00:00.000Z");

describe("billing-renewal job", () => {
  it("renews an elapsed monthly period and invoices it in full", async () => {
    const tenant = await tenantWith("starter", {
      seats: 4,
      currentPeriodStart: "2026-05-10T09:00:00.000Z",
      currentPeriodEnd: "2026-06-10T09:00:00.000Z",
    });

    const result = await runBillingRenewalJob(NOW);

    expect(result.kind).toBe("billing-renewal");
    expect(result.processed).toBeGreaterThanOrEqual(1);
    expect(result.failed).toBe(0);

    const subscription = await subscriptionOf(tenant);
    expect(subscription.currentPeriodStart).toBe("2026-06-10T09:00:00.000Z");
    expect(subscription.currentPeriodEnd).toBe("2026-07-10T09:00:00.000Z");
    expect(subscription.status).toBe("active");

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      orgId: tenant.org.id,
      amountCents: 900 * 4,
      currency: "usd",
      periodStart: "2026-06-10T09:00:00.000Z",
      periodEnd: "2026-07-10T09:00:00.000Z",
      paidAt: null,
    });
  });

  it("leaves a period that has not ended alone, and renews one ending exactly now", async () => {
    const future = await tenantWith("starter", {
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-15T12:00:00.001Z",
    });
    const exact = await tenantWith("starter", {
      currentPeriodStart: "2026-05-15T12:00:00.000Z",
      currentPeriodEnd: "2026-06-15T12:00:00.000Z",
    });

    await runBillingRenewalJob(NOW);

    expect(await invoiceRepo.listInvoices(future.org.id)).toHaveLength(0);
    expect((await subscriptionOf(future)).currentPeriodEnd).toBe("2026-06-15T12:00:00.001Z");
    expect(await invoiceRepo.listInvoices(exact.org.id)).toHaveLength(1);
    expect((await subscriptionOf(exact)).currentPeriodEnd).toBe("2026-07-15T12:00:00.000Z");
  });

  it("catches a subscription that is several periods behind up, one invoice per period", async () => {
    const tenant = await tenantWith("growth", {
      seats: 2,
      currentPeriodStart: "2026-01-31T00:00:00.000Z",
      currentPeriodEnd: "2026-02-28T00:00:00.000Z",
    });
    // Behind by Feb 28 → Mar 28 → Apr 28 → May 28 (four), and Jun 28 is still ahead.

    await runBillingRenewalJob(NOW);

    const subscription = await subscriptionOf(tenant);
    expect(subscription.currentPeriodStart).toBe("2026-05-28T00:00:00.000Z");
    expect(subscription.currentPeriodEnd).toBe("2026-06-28T00:00:00.000Z");

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => [invoice.periodStart, invoice.periodEnd])).toEqual([
      ["2026-05-28T00:00:00.000Z", "2026-06-28T00:00:00.000Z"],
      ["2026-04-28T00:00:00.000Z", "2026-05-28T00:00:00.000Z"],
      ["2026-03-28T00:00:00.000Z", "2026-04-28T00:00:00.000Z"],
    ]);
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);
    expect(invoices.every((invoice) => invoice.amountCents === 1_900 * 2)).toBe(true);
  });

  it("clamps month ends and carries the clamped day forward", async () => {
    const tenant = await tenantWith("starter", {
      currentPeriodStart: "2025-12-31T06:00:00.000Z",
      currentPeriodEnd: "2026-01-31T06:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-30T00:00:00.000Z"));

    const periods = (await invoiceRepo.listInvoices(tenant.org.id)).map((invoice) => [
      invoice.periodStart,
      invoice.periodEnd,
    ]);
    expect(periods).toEqual([
      ["2026-02-28T06:00:00.000Z", "2026-03-28T06:00:00.000Z"],
      ["2026-01-31T06:00:00.000Z", "2026-02-28T06:00:00.000Z"],
    ].slice(0, 2).concat([["2026-03-28T06:00:00.000Z", "2026-04-28T06:00:00.000Z"]]).sort((a, b) => (a[0]! < b[0]! ? 1 : -1)));
  });

  it("charges twelve months for an annual period, which ends on the same day next year", async () => {
    const tenant = await tenantWith("starter", {
      interval: "annual",
      seats: 3,
      currentPeriodStart: "2027-02-28T00:00:00.000Z",
      currentPeriodEnd: "2028-02-29T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2028-03-01T00:00:00.000Z"));

    const [invoice] = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoice).toMatchObject({
      amountCents: 900 * 3 * 12,
      periodStart: "2028-02-29T00:00:00.000Z",
      periodEnd: "2029-02-28T00:00:00.000Z",
    });
  });

  it("moves free periods on without invoicing", async () => {
    const tenant = await tenantWith("free", {
      currentPeriodStart: "2026-03-01T00:00:00.000Z",
      currentPeriodEnd: "2026-04-01T00:00:00.000Z",
    });
    const issued = capture("billing.invoice_issued");
    const before = issued.length;

    await runBillingRenewalJob(NOW);

    const subscription = await subscriptionOf(tenant);
    expect(subscription.currentPeriodStart).toBe("2026-05-01T00:00:00.000Z");
    expect(subscription.currentPeriodEnd).toBe("2026-06-01T00:00:00.000Z");
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
    expect(issued.filter((e) => e.orgId === tenant.org.id)).toHaveLength(before);
  });

  it("publishes, audits and announces each invoice exactly once, to the owner only", async () => {
    const tenant = await tenantWith("starter", {
      seats: 2,
      currentPeriodStart: "2026-04-10T00:00:00.000Z",
      currentPeriodEnd: "2026-05-10T00:00:00.000Z",
    });
    const issued = capture("billing.invoice_issued");

    await runBillingRenewalJob(NOW);
    await runBillingRenewalJob(NOW);

    const mine = issued.filter((event) => event.orgId === tenant.org.id);
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(2);
    expect(mine).toHaveLength(2);
    expect(mine.map((event) => event.invoiceId).sort()).toEqual(
      invoices.map((invoice) => invoice.id).sort(),
    );
    expect(mine[0]).toMatchObject({
      actorId: null,
      amountCents: 1_800,
      periodStart: "2026-04-10T00:00:00.000Z",
      periodEnd: "2026-05-10T00:00:00.000Z",
    });

    const audit = await activityFor(tenant, "billing.invoice_issued");
    expect(audit).toHaveLength(2);
    expect(audit.every((row) => row.subjectKind === "subscription")).toBe(true);
    expect(audit.every((row) => row.subjectId === tenant.org.id)).toBe(true);

    expect(await notificationsFor(tenant, "owner")).toHaveLength(2);
    for (const other of ["admin", "member", "viewer"] as const) {
      expect(await notificationsFor(tenant, other)).toHaveLength(0);
    }
  });

  it("is replay-safe at the same instant", async () => {
    const tenant = await tenantWith("growth", {
      currentPeriodStart: "2026-03-10T00:00:00.000Z",
      currentPeriodEnd: "2026-04-10T00:00:00.000Z",
    });
    const canceled = await tenantWith("growth", {
      status: "canceled",
      cancelAt: "2026-05-01T00:00:00.000Z",
      currentPeriodStart: "2026-04-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-01T00:00:00.000Z",
    });
    const changed = capture("billing.plan_changed");

    await runBillingRenewalJob(NOW);
    const afterFirst = [await subscriptionOf(tenant), await subscriptionOf(canceled)];
    const invoicesFirst = await invoiceRepo.listInvoices(tenant.org.id);
    const changesFirst = changed.length;

    const second = await runBillingRenewalJob(NOW);

    expect([await subscriptionOf(tenant), await subscriptionOf(canceled)]).toEqual(afterFirst);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual(invoicesFirst);
    expect(changed).toHaveLength(changesFirst);
    expect(second.failed).toBe(0);
  });

  describe("cancellation", () => {
    it("does nothing before the cancellation date, whatever the period end says", async () => {
      const tenant = await tenantWith("growth", {
        status: "canceled",
        cancelAt: "2026-06-20T00:00:00.000Z",
        currentPeriodStart: "2026-05-01T00:00:00.000Z",
        currentPeriodEnd: "2026-06-01T00:00:00.000Z",
      });
      const before = await subscriptionOf(tenant);
      const changed = capture("billing.plan_changed");
      const seen = changed.length;

      await runBillingRenewalJob(NOW);

      expect(await subscriptionOf(tenant)).toEqual(before);
      expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
      expect(changed).toHaveLength(seen);
    });

    it("moves the workspace to the free plan as of the cancellation date", async () => {
      const tenant = await tenantWith("growth", {
        status: "canceled",
        cancelAt: "2026-06-10T08:00:00.000Z",
        currentPeriodStart: "2026-05-10T08:00:00.000Z",
        currentPeriodEnd: "2026-06-10T08:00:00.000Z",
      });
      const changed = capture("billing.plan_changed");

      await runBillingRenewalJob(NOW);
      await runBillingRenewalJob(NOW);

      const subscription = await subscriptionOf(tenant);
      expect(subscription).toMatchObject({
        plan: "free",
        status: "active",
        cancelAt: null,
        interval: "monthly",
        currentPeriodStart: "2026-06-10T08:00:00.000Z",
        currentPeriodEnd: "2026-07-10T08:00:00.000Z",
      });
      expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);

      const mine = changed.filter((event) => event.orgId === tenant.org.id);
      expect(mine).toHaveLength(1);
      expect(mine[0]).toMatchObject({ from: "growth", to: "free", actorId: null });
      expect(await activityFor(tenant, "billing.plan_changed")).toHaveLength(1);
    });

    it("keeps rolling the free periods when the cancellation is long past", async () => {
      const tenant = await tenantWith("starter", {
        status: "canceled",
        cancelAt: "2026-03-20T00:00:00.000Z",
        currentPeriodStart: "2026-02-20T00:00:00.000Z",
        currentPeriodEnd: "2026-03-20T00:00:00.000Z",
      });

      await runBillingRenewalJob(NOW);
      const first = await subscriptionOf(tenant);
      await runBillingRenewalJob(NOW);

      expect(first).toMatchObject({
        plan: "free",
        status: "active",
        currentPeriodStart: "2026-05-20T00:00:00.000Z",
        currentPeriodEnd: "2026-06-20T00:00:00.000Z",
      });
      expect(await subscriptionOf(tenant)).toEqual(first);
      expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
    });

    it("takes effect through a cancelSubscription at period end", async () => {
      const tenant = await tenantWith("starter", {
        currentPeriodStart: "2026-06-01T00:00:00.000Z",
        currentPeriodEnd: "2026-06-20T00:00:00.000Z",
      });
      await billingService.cancelSubscription(tenant.actors.owner, {
        orgId: tenant.org.id,
        cancelImmediately: false,
      });

      await runBillingRenewalJob(NOW);
      expect((await subscriptionOf(tenant)).status).toBe("canceled");

      await runBillingRenewalJob(new Date("2026-06-20T00:00:00.000Z"));
      expect(await subscriptionOf(tenant)).toMatchObject({ plan: "free", status: "active" });
    });
  });

  it("leaves trialing and past-due subscriptions alone", async () => {
    const trial = await tenantWith("starter", {
      status: "trialing",
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-15T00:00:00.000Z",
    });
    const pastDue = await tenantWith("starter", {
      status: "past_due",
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-15T00:00:00.000Z",
    });
    const before = [await subscriptionOf(trial), await subscriptionOf(pastDue)];

    await runBillingRenewalJob(NOW);

    expect([await subscriptionOf(trial), await subscriptionOf(pastDue)]).toEqual(before);
    expect(await invoiceRepo.listInvoices(trial.org.id)).toHaveLength(0);
    expect(await invoiceRepo.listInvoices(pastDue.org.id)).toHaveLength(0);
  });

  it("skips archived workspaces entirely", async () => {
    const renewing = await tenantWith("starter", {
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });
    const canceling = await tenantWith("starter", {
      status: "canceled",
      cancelAt: "2026-06-01T00:00:00.000Z",
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });
    await orgRepo.archiveOrg(renewing.org.id);
    await orgRepo.archiveOrg(canceling.org.id);
    const before = [await subscriptionOf(renewing), await subscriptionOf(canceling)];

    await runBillingRenewalJob(NOW);

    expect([await subscriptionOf(renewing), await subscriptionOf(canceling)]).toEqual(before);
    expect(await invoiceRepo.listInvoices(renewing.org.id)).toHaveLength(0);
  });

  it("sweeps every workspace, however many there are", async () => {
    const tenants: Tenant[] = [];
    for (let index = 0; index < 60; index += 1) {
      tenants.push(
        await tenantWith("starter", {
          currentPeriodStart: "2026-05-01T00:00:00.000Z",
          currentPeriodEnd: "2026-06-01T00:00:00.000Z",
        }),
      );
    }

    await runBillingRenewalJob(NOW);

    for (const tenant of tenants) {
      expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(1);
    }
  });

  it("numbers invoices uniquely within a workspace", async () => {
    const tenant = await tenantWith("starter", {
      currentPeriodStart: "2025-06-01T00:00:00.000Z",
      currentPeriodEnd: "2025-07-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(NOW);

    const numbers = (await invoiceRepo.listInvoices(tenant.org.id)).map((invoice) => invoice.number);
    expect(numbers).toHaveLength(12);
    expect(new Set(numbers).size).toBe(12);
  });

  it("runs from the queue under the billing-renewal kind", async () => {
    const tenant = await tenantWith("starter", {
      currentPeriodStart: toIsoTimestamp(new Date(Date.now() - 40 * 86_400_000)),
      currentPeriodEnd: toIsoTimestamp(new Date(Date.now() - 10 * 86_400_000)),
    });

    enqueue({
      id: "billing-renewal:test",
      kind: "billing-renewal",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(1);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(1);
  });

  it("does not touch another workspace's invoices", async () => {
    const a = await tenantWith("starter", {
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });
    const b = await tenantWith("starter", {
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(NOW);

    expect(await invoiceRepo.listInvoices(a.org.id as OrgId)).toHaveLength(1);
    expect(await invoiceRepo.listInvoices(b.org.id as OrgId)).toHaveLength(0);
  });
});

