    expect(await invoiceRepo.listInvoices(future.org.id)).toHaveLength(0);
    expect((await subscriptionOf(future)).currentPeriodEnd).toBe("2026-06-15T12:00:00.001Z");
    expect(await invoiceRepo.listInvoices(exact.org.id)).toHaveLength(1);
    expect((await subscriptionOf(exact)).currentPeriodEnd).toBe("2026-07-15T12:00:00.000Z");
  });

  it("catches a subscription that is several periods behind up, one invoice per period", async () => {
    const tenant = await tenantWith("growth", {
      seats: 2,
      currentPeriodStart: "2026-01-31T00:00:00.000Z",
      currentPeriodEnd: "2026-02-28T00:00:00.000Z",
    });
    // Behind by Feb 28 → Mar 28 → Apr 28 → May 28 (four), and Jun 28 is still ahead.

    await runBillingRenewalJob(NOW);

    const subscription = await subscriptionOf(tenant);
    expect(subscription.currentPeriodStart).toBe("2026-05-28T00:00:00.000Z");
    expect(subscription.currentPeriodEnd).toBe("2026-06-28T00:00:00.000Z");

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => [invoice.periodStart, invoice.periodEnd])).toEqual([
      ["2026-05-28T00:00:00.000Z", "2026-06-28T00:00:00.000Z"],
      ["2026-04-28T00:00:00.000Z", "2026-05-28T00:00:00.000Z"],
      ["2026-03-28T00:00:00.000Z", "2026-04-28T00:00:00.000Z"],
