  it("clamps month ends and carries the clamped day forward", async () => {
    const tenant = await tenantWith("starter", {
      currentPeriodStart: "2025-12-31T06:00:00.000Z",
      currentPeriodEnd: "2026-01-31T06:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-30T00:00:00.000Z"));

    const periods = (await invoiceRepo.listInvoices(tenant.org.id)).map((invoice) => [
