      currentPeriodStart: "2026-04-10T00:00:00.000Z",
      currentPeriodEnd: "2026-05-10T00:00:00.000Z",
    });
    const issued = capture("billing.invoice_issued");

    await runBillingRenewalJob(NOW);
    await runBillingRenewalJob(NOW);

    const mine = issued.filter((event) => event.orgId === tenant.org.id);
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(2);
    expect(mine).toHaveLength(2);
