    expect(audit).toHaveLength(2);
    expect(audit.every((row) => row.subjectKind === "subscription")).toBe(true);
    expect(audit.every((row) => row.subjectId === tenant.org.id)).toBe(true);

    expect(await notificationsFor(tenant, "owner")).toHaveLength(2);
    for (const other of ["admin", "member", "viewer"] as const) {
      expect(await notificationsFor(tenant, other)).toHaveLength(0);
    }
  });

  it("is replay-safe at the same instant", async () => {
    const tenant = await tenantWith("growth", {
      currentPeriodStart: "2026-03-10T00:00:00.000Z",
      currentPeriodEnd: "2026-04-10T00:00:00.000Z",
    });
    const canceled = await tenantWith("growth", {
      status: "canceled",
      cancelAt: "2026-05-01T00:00:00.000Z",
      currentPeriodStart: "2026-04-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-01T00:00:00.000Z",
    });
    const changed = capture("billing.plan_changed");

    await runBillingRenewalJob(NOW);
    const afterFirst = [await subscriptionOf(tenant), await subscriptionOf(canceled)];
    const invoicesFirst = await invoiceRepo.listInvoices(tenant.org.id);
    const changesFirst = changed.length;

    const second = await runBillingRenewalJob(NOW);

    expect([await subscriptionOf(tenant), await subscriptionOf(canceled)]).toEqual(afterFirst);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual(invoicesFirst);
