  describe("cancellation", () => {
    it("does nothing before the cancellation date, whatever the period end says", async () => {
      const tenant = await tenantWith("growth", {
        status: "canceled",
        cancelAt: "2026-06-20T00:00:00.000Z",
        currentPeriodStart: "2026-05-01T00:00:00.000Z",
        currentPeriodEnd: "2026-06-01T00:00:00.000Z",
