        status: "canceled",
        cancelAt: "2026-06-10T08:00:00.000Z",
        currentPeriodStart: "2026-05-10T08:00:00.000Z",
        currentPeriodEnd: "2026-06-10T08:00:00.000Z",
      });
      const changed = capture("billing.plan_changed");

      await runBillingRenewalJob(NOW);
      await runBillingRenewalJob(NOW);

      const subscription = await subscriptionOf(tenant);
      expect(subscription).toMatchObject({
        plan: "free",
        status: "active",
        cancelAt: null,
        interval: "monthly",
        currentPeriodStart: "2026-06-10T08:00:00.000Z",
        currentPeriodEnd: "2026-07-10T08:00:00.000Z",
      });
      expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);

      const mine = changed.filter((event) => event.orgId === tenant.org.id);
