    const tenants: Tenant[] = [];
    for (let index = 0; index < 60; index += 1) {
      tenants.push(
        await tenantWith("starter", {
          currentPeriodStart: "2026-05-01T00:00:00.000Z",
          currentPeriodEnd: "2026-06-01T00:00:00.000Z",
        }),
      );
    }

    await runBillingRenewalJob(NOW);

    for (const tenant of tenants) {
      expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(1);
    }
  });

  it("numbers invoices uniquely within a workspace", async () => {
    const tenant = await tenantWith("starter", {
      currentPeriodStart: "2025-06-01T00:00:00.000Z",
      currentPeriodEnd: "2025-07-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(NOW);

    const numbers = (await invoiceRepo.listInvoices(tenant.org.id)).map((invoice) => invoice.number);
