    expect(new Set(numbers).size).toBe(12);
  });

  it("runs from the queue under the billing-renewal kind", async () => {
    const tenant = await tenantWith("starter", {
      currentPeriodStart: toIsoTimestamp(new Date(Date.now() - 40 * 86_400_000)),
      currentPeriodEnd: toIsoTimestamp(new Date(Date.now() - 10 * 86_400_000)),
    });

    enqueue({
      id: "billing-renewal:test",
      kind: "billing-renewal",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(1);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(1);
  });

  it("does not touch another workspace's invoices", async () => {
    const a = await tenantWith("starter", {
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });
    const b = await tenantWith("starter", {
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(NOW);

    expect(await invoiceRepo.listInvoices(a.org.id as OrgId)).toHaveLength(1);
    expect(await invoiceRepo.listInvoices(b.org.id as OrgId)).toHaveLength(0);
  });
});

