/**
 * Renewal, invoicing and cancellation as the hourly job performs them.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import { drain, enqueue, resetQueue } from "@/server/jobs";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SubscriptionRow } from "@/server/db";
import type { PlanId } from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { TaskflowEventType, TaskflowEventPayload, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let slugCounter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
});

afterEach(() => {
  resetQueue();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

function capture<K extends TaskflowEventType>(type: K): TaskflowEventPayload<K>[] {
  const seen: TaskflowEventPayload<K>[] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function tenantWith(
  plan: PlanId,
  state: Partial<
    Pick<
      SubscriptionRow,
      "interval" | "status" | "seats" | "currentPeriodStart" | "currentPeriodEnd" | "cancelAt"
    >
  >,
): Promise<Tenant> {
  slugCounter += 1;
  const tenant = await createTenant(`renewal-${slugCounter}`, plan);
  getDb()
    .update(subscriptions)
    .set({ plan, status: "active", ...state })
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
  return tenant;
}

async function subscriptionOf(tenant: Tenant) {
  const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
  if (!subscription) throw new Error("missing subscription");
  return subscription;
}

async function activityFor(tenant: Tenant, action: "billing.invoice_issued" | "billing.plan_changed") {
  const page = await activityRepo.listActivity({
    orgId: tenant.org.id,
    action: [action],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

async function notificationsFor(tenant: Tenant, recipient: keyof Tenant["userIds"]) {
  const page = await notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds[recipient],
    unreadOnly: false,
    kind: ["invoice_issued"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

