    });
    const issued = capture("billing.invoice_issued");
    const before = issued.length;

    await runBillingRenewalJob(NOW);

    const subscription = await subscriptionOf(tenant);
    expect(subscription.currentPeriodStart).toBe("2026-05-01T00:00:00.000Z");
    expect(subscription.currentPeriodEnd).toBe("2026-06-01T00:00:00.000Z");
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
    expect(issued.filter((e) => e.orgId === tenant.org.id)).toHaveLength(before);
