 * Mid-period changes: `updateSeats` and `changePlan` charge for the rest of
 * the current period, and an invoice is issued like a renewal invoice.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import "@/server/services/notification-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SubscriptionRow } from "@/server/db";
import type { BillingInterval, PlanId } from "@/types/billing";
import type { TaskflowEventPayload, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let slugCounter = 0;

// A 30-day period. At the moment of the call below 14 days and 12 hours are left: 15 started days.
const PERIOD_START = "2026-06-01T00:00:00.000Z";
const PERIOD_END = "2026-07-01T00:00:00.000Z";
const MID_PERIOD = new Date("2026-06-16T12:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
});

beforeEach(() => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(MID_PERIOD);
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

async function tenantWith(
  plan: PlanId,
  state: Partial<
    Pick<SubscriptionRow, "interval" | "status" | "seats" | "currentPeriodStart" | "currentPeriodEnd">
  > = {},
): Promise<Tenant> {
  slugCounter += 1;
  const tenant = await createTenant(`proration-${slugCounter}`, plan);
  getDb()
    .update(subscriptions)
    .set({
      plan,
      status: "active",
      seats: 3,
      currentPeriodStart: PERIOD_START,
      currentPeriodEnd: PERIOD_END,
      ...state,
    })
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
  return tenant;
}

