const setSeats = (tenant: Tenant, seats: number) =>
  billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats });

const setPlan = (tenant: Tenant, plan: PlanId, interval: BillingInterval = "monthly") =>
  billingService.changePlan(tenant.actors.owner, { orgId: tenant.org.id, plan, interval });

