  it("charges the added seats for the days left, and keeps the period", async () => {
    const tenant = await tenantWith("starter");

    const subscription = await setSeats(tenant, 5);

    expect(subscription.seats).toBe(5);
    expect(subscription.currentPeriodStart).toBe(PERIOD_START);
    expect(subscription.currentPeriodEnd).toBe(PERIOD_END);

    // 900 × 2 seats × 1 month = 1800, × 15/30.
    expect(await invoicesOf(tenant)).toMatchObject([
      {
        amountCents: 900,
        currency: "usd",
        periodStart: PERIOD_START,
        periodEnd: PERIOD_END,
        paidAt: null,
      },
    ]);
  });

  it("rounds the charge down to whole cents", async () => {
    const tenant = await tenantWith("growth", {
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });
    vi.setSystemTime(new Date("2026-06-24T00:00:00.000Z")); // 7 days left

    await setSeats(tenant, 4);

    expect((await invoicesOf(tenant))[0]?.amountCents).toBe(443); // 1900 × 7 / 30 = 443.33
  });

  it("charges twelve months of the added seats on an annual period", async () => {
    const tenant = await tenantWith("starter", {
      interval: "annual",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2027-01-01T00:00:00.000Z", // 365 days
    });
    vi.setSystemTime(new Date("2026-07-02T00:00:00.000Z")); // 183 days left

    await setSeats(tenant, 4);

    expect((await invoicesOf(tenant))[0]?.amountCents).toBe(Math.floor((900 * 1 * 12 * 183) / 365));
  });

  it("charges and credits nothing for removed seats", async () => {
    const tenant = await tenantWith("starter");

    const subscription = await setSeats(tenant, 1);

    expect(subscription.seats).toBe(1);
    expect(await invoicesOf(tenant)).toHaveLength(0);
  });

  it("charges nothing on the free plan or during a trial", async () => {
    const free = await tenantWith("free");
    const trial = await tenantWith("growth", { status: "trialing" });

    await setSeats(free, 3);
    expect((await subscriptionOf(free)).seats).toBe(3);
    await setSeats(trial, 9);

    expect((await subscriptionOf(trial)).seats).toBe(9);
    expect(await invoicesOf(free)).toHaveLength(0);
    expect(await invoicesOf(trial)).toHaveLength(0);
  });

  it("charges nothing once the period end has been reached, or when the charge rounds to zero", async () => {
    const lapsed = await tenantWith("starter");
    vi.setSystemTime(new Date("2026-07-01T00:00:00.000Z"));
    await setSeats(lapsed, 10);
    expect(await invoicesOf(lapsed)).toHaveLength(0);

    // 9 cents a seat-month would be 0.3 cents with one day of 30 left.
    const cheap = await tenantWith("starter");
    vi.setSystemTime(new Date("2026-06-30T12:00:00.000Z"));
    await setSeats(cheap, 4); // 900 × 1 × 1/30 = 30 cents, not zero
    expect((await invoicesOf(cheap))[0]?.amountCents).toBe(30);
  });

  it("still refuses seats above the plan's ceiling, without writing anything", async () => {
    const tenant = await tenantWith("starter");

    await expect(setSeats(tenant, 11)).rejects.toThrow(/tops out at 10 seats/);

    expect((await subscriptionOf(tenant)).seats).toBe(3);
    expect(await invoicesOf(tenant)).toHaveLength(0);
  });

  it("publishes, audits and announces the invoice once, to the owner only", async () => {
    const tenant = await tenantWith("starter");
    const issued: TaskflowEventPayload<"billing.invoice_issued">[] = [];
    detachers.push(subscribe("billing.invoice_issued", (payload) => void issued.push(payload)));

    await setSeats(tenant, 6);

    const [invoice] = await invoicesOf(tenant);
    const mine = issued.filter((event) => event.orgId === tenant.org.id);
    expect(mine).toHaveLength(1);
    expect(mine[0]).toMatchObject({
      invoiceId: invoice?.id,
      invoiceNumber: invoice?.number,
      amountCents: invoice?.amountCents,
      periodStart: PERIOD_START,
      periodEnd: PERIOD_END,
    });

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 10,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      subjectKind: "subscription",
      subjectId: tenant.org.id,
    });

    const told = async (role: keyof Tenant["userIds"]) =>
      (
        await notificationRepo.listNotifications({
          orgId: tenant.org.id,
          recipientId: tenant.userIds[role],
          unreadOnly: false,
          kind: ["invoice_issued"],
          limit: 10,
          cursor: null,
        })
      ).items;
    expect(await told("owner")).toHaveLength(1);
    expect(await told("admin")).toHaveLength(0);
    expect(await told("member")).toHaveLength(0);
  });
});

describe("changePlan", () => {
  it("charges the per-seat price difference for the days left on an upgrade between paid plans", async () => {
    const tenant = await tenantWith("starter", { seats: 4 });

    const subscription = await setPlan(tenant, "growth");

    expect(subscription).toMatchObject({
