      status: "active",
      currentPeriodStart: "2026-06-10T00:00:00.000Z",
      currentPeriodEnd: "2026-06-24T00:00:00.000Z",
    });
    expect(await invoicesOf(tenant)).toHaveLength(0);
  });

  it("starts a fresh, fully invoiced period when leaving the free plan", async () => {
    const tenant = await tenantWith("free", { seats: 3 });

    const subscription = await setPlan(tenant, "starter", "annual");

    expect(subscription).toMatchObject({
      plan: "starter",
      interval: "annual",
      status: "active",
      currentPeriodStart: "2026-06-16T12:00:00.000Z",
      currentPeriodEnd: "2027-06-16T12:00:00.000Z",
    });
    expect(await invoicesOf(tenant)).toMatchObject([
