        amountCents: 900 * 3 * 12,
        periodStart: "2026-06-16T12:00:00.000Z",
        periodEnd: "2027-06-16T12:00:00.000Z",
      },
    ]);
  });

  it("still refuses a downgrade the usage would breach, without writing anything", async () => {
    const tenant = await tenantWith("growth");
    const { incrementUsage } = await import("@/server/repositories/usage-repository");
    await incrementUsage(tenant.org.id, { seatsUsed: 5 });

    await expect(setPlan(tenant, "free")).rejects.toThrow(/seats exceeds its limit/);

    expect((await subscriptionOf(tenant)).plan).toBe("growth");
    expect(await invoicesOf(tenant)).toHaveLength(0);
