/** A subscription rewrite together with the invoices it brings. */
export type SubscriptionChange = {
  readonly patch: SubscriptionPatch;
  readonly invoices: readonly NewInvoiceLine[];
};

export type SubscriptionTransition = {
  readonly before: Subscription;
  readonly after: Subscription;
  readonly invoices: readonly Invoice[];
};

/**
 * Reads the org's subscription, lets `decide` turn it into a change and
 * commits that change and its invoices in one transaction. `decide` runs on
 * the row as it is inside the transaction and must be synchronous, which is
 * what makes a repeated or concurrent run see the earlier run's result and
 * decline (`null`) instead of charging again.
 */
export async function transactSubscription(
  orgId: OrgId,
  decide: (current: Subscription) => SubscriptionChange | null,
): Promise<SubscriptionTransition | null> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(subscriptions)
      .where(orgPredicate(subscriptions.orgId, orgId))
      .get();
    if (!current) throw new Error(`Subscription for org ${orgId} not found`);

    const before = toSubscription(current);
    const change = decide(before);
    if (change === null) return null;

    const row = tx
      .update(subscriptions)
      .set({ ...change.patch, updatedAt: toIsoTimestamp(new Date()) })
      .where(
        and(
          orgPredicate(subscriptions.orgId, orgId),
          eq(subscriptions.id, before.id),
        ),
      )
      .returning()
      .get();
    if (!row) throw new Error(`Subscription for org ${orgId} not found`);

    return {
      before,
      after: toSubscription(row),
      invoices: change.invoices.map((line) =>
        issueInvoiceInTransaction(tx, orgId, line),
      ),
    };
  }, { behavior: "immediate" });
}

/**
 * Feeds the billing-renewal job: every subscription that is billed or about to
 * end, except those of archived workspaces. Cross-tenant and unbatched by
 * design, it sweeps every org. Which of them are due is for the job to decide.

